import React, { useState, useEffect } from 'react';
import DraggableModal from '@shared/components/modal/modal/DraggableModal';
import LadderCounterProposalModal from './LadderCounterProposalModal';
import { BACKEND_URL } from '@shared/config/config.js';
import { supabaseDataService } from '@shared/services/services/supabaseDataService.js';
import { formatDateForDisplay } from '@shared/utils/utils/dateUtils.js';
import { CHALLENGE_CONFIRM_MATCH_FEE_BLURB } from '@shared/utils/utils/ladderPaymentCopy.js';
import './LadderChallengeConfirmModal.css';

const LadderChallengeConfirmModal = ({ 
  isOpen, 
  onClose, 
  challenge, 
  currentUser,
  onChallengeResponse 
}) => {
  const [userNote, setUserNote] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [showCounterModal, setShowCounterModal] = useState(false);
  const [selectedDate, setSelectedDate] = useState('');
  const [declineStatus, setDeclineStatus] = useState(null);
  const [loadingDeclineStatus, setLoadingDeclineStatus] = useState(false);

  // Fetch decline status when modal opens
  useEffect(() => {
    if (isOpen && currentUser) {
      fetchDeclineStatus();
    }
  }, [isOpen, currentUser]);

  const fetchDeclineStatus = async () => {
    setLoadingDeclineStatus(true);
    try {
      const email = currentUser.email || currentUser.unifiedAccount?.email;
      
      console.log('🔍 Fetching decline status from Supabase for:', email);
      
      // Use Supabase service to get decline status
      const result = await supabaseDataService.getPlayerDeclineStatus(email);
      
      if (result.success) {
        console.log('🔍 Decline status from Supabase:', result.declineStatus);
        setDeclineStatus(result.declineStatus);
      } else {
        console.error('Failed to fetch decline status:', result.error);
        setDeclineStatus(null);
      }
    } catch (error) {
      console.error('Error fetching decline status:', error);
      setDeclineStatus(null);
    } finally {
      setLoadingDeclineStatus(false);
    }
  };

  const handleAccept = async () => {
    setLoading(true);
    setError('');

    try {
      // Use Supabase instead of old backend API
      const result = await supabaseDataService.acceptChallenge(challenge._id || challenge.id, {
        note: userNote,
        selectedDate: selectedDate
      });

      if (!result.success) {
        throw new Error(result.error || 'Failed to accept challenge');
      }

      // Send confirmation email
      const challengerEmail = challenger.email || challenge.challenger_email;
      await sendConfirmationEmail({
        to_email: challengerEmail,
        to_name: `${challengerName} ${challengerLastName}`.trim(),
        from_name: `${currentUser.firstName || currentUser.first_name || ''} ${currentUser.lastName || currentUser.last_name || ''}`.trim(),
        challenge_type: challengeType,
        entry_fee: md.entryFee,
        race_length: md.raceLength,
        game_type: md.gameType,
        location: md.location,
        note: userNote,
        challenge_id: challenge._id || challenge.id,
        match_date: selectedDate
      });

      if (onChallengeResponse) {
        onChallengeResponse('accepted', result);
      }
      
      onClose();
    } catch (err) {
      console.error('Error accepting challenge:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleDecline = async () => {
    setLoading(true);
    setError('');

    try {
      // Use Supabase instead of old backend API
      const result = await supabaseDataService.declineChallenge(challenge._id || challenge.id, {
        note: userNote,
        defenderEmail: currentUser.email || currentUser.unifiedAccount?.email
      });

      if (!result.success) {
        throw new Error(result.error || 'Failed to decline challenge');
      }

      // Send decline notification email to challenger
      try {
        const challengerEmail = challenger.email || challenge.challenger_email;
        const emailNotificationService = (await import('@shared/services/services/emailNotificationService.js')).default;
        await emailNotificationService.sendChallengeDeclined({
          challengerEmail,
          challengerName: `${challengerName} ${challengerLastName}`.trim(),
          defenderName: `${currentUser.firstName || currentUser.first_name || ''} ${currentUser.lastName || currentUser.last_name || ''}`.trim(),
          challengerPosition: challengerPos,
          defenderPosition: defenderPos,
          ladderName: defenderLadder,
          declineReason: userNote || 'No reason provided'
        });
        console.log('📧 Challenge declined email sent to challenger');
      } catch (emailError) {
        console.error('Failed to send decline email:', emailError);
        // Don't fail the decline if email fails
      }

      if (onChallengeResponse) {
        onChallengeResponse('declined', result);
      }
      
      // Refresh decline status after declining
      await fetchDeclineStatus();
      
      onClose();
    } catch (err) {
      console.error('Error declining challenge:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleCounter = () => {
    setShowCounterModal(true);
  };

  const sendConfirmationEmail = async (emailData) => {
    try {
      const response = await fetch(`${BACKEND_URL}/api/email/send-challenge-confirmation`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(emailData),
      });

      if (!response.ok) {
        console.error('Failed to send confirmation email');
      }
    } catch (error) {
      console.error('Error sending confirmation email:', error);
    }
  };

  const getChallengeTypeDescription = (type) => {
    const descriptions = {
      'challenge': 'Challenge Match',
      'smackdown': 'SmackDown Match',
      'smackback': 'SmackBack Match',
      'fast-track': 'Fast Track Challenge'
    };
    return descriptions[type] || type;
  };

  const getPositionChangeDescription = (type) => {
    const t = type ?? challenge.challengeType ?? challenge.challenge_type ?? 'challenge';
    if (t === 'challenge') {
      return 'If you win: Positions remain unchanged. If challenger wins: You switch positions.';
    } else if (t === 'smackdown') {
      return 'If challenger wins: You move 3 spots down, challenger moves 2 spots up. If you win: You switch positions.';
    } else if (t === 'smackback') {
      return 'If challenger wins: They move to 1st place, all others move down. If you win: Positions remain unchanged.';
    } else if (t === 'fast-track') {
      return 'If challenger wins: They take your position, you move to their old spot, others between move down one. If you win: Positions remain unchanged.';
    }
    return '';
  };

  if (!isOpen || !challenge) return null;

  // Normalize challenge for both Supabase format (flat) and legacy format (nested matchDetails)
  const challenger = challenge.challenger || {};
  const defender = challenge.defender || {};
  const matchDetails = challenge.matchDetails || {};
  const md = {
    entryFee: matchDetails.entryFee ?? (challenge.entry_fee ?? 0),
    raceLength: matchDetails.raceLength ?? (matchDetails.race_length ?? (challenge.match_format ? parseInt(String(challenge.match_format).replace(/\D/g, ''), 10) || 5 : 5)),
    gameType: matchDetails.gameType ?? matchDetails.game_type ?? '8-Ball',
    tableSize: matchDetails.tableSize ?? matchDetails.table_size ?? '7-foot',
    location: matchDetails.location ?? challenge.proposed_location ?? 'TBD',
    preferredDates: matchDetails.preferredDates ?? matchDetails.preferred_dates ?? []
  };
  const challengerName = challenger.firstName || challenger.first_name || challenge.challenger_name || 'Unknown';
  const challengerLastName = challenger.lastName || challenger.last_name || '';
  const defenderName = defender.firstName || defender.first_name || challenge.defender_name || 'Unknown';
  const defenderLastName = defender.lastName || defender.last_name || '';
  const challengerPos = challenger.position ?? challenge.challenger_position ?? '?';
  const defenderPos = defender.position ?? challenge.defender_position ?? '?';
  const challengerLadder = challenger.ladderName ?? challenge.challenger_ladder_name ?? '';
  const defenderLadder = defender.ladderName ?? challenge.defender_ladder_name ?? '';
  const challengeType = challenge.challengeType ?? challenge.challenge_type ?? 'challenge';
  const deadline = challenge.deadline ?? challenge.expires_at;
  const postContent = challenge.challengePost?.postContent ?? challenge.challenge_post?.post_content ?? challenge.post_content ?? '';
  const isSentChallenge = currentUser && (challenger.email === currentUser.email || (currentUser.unifiedAccount?.email && challenger.email === currentUser.unifiedAccount.email));

  return (
    <DraggableModal
      open={true}
      onClose={onClose}
      title={`🎯 ${getChallengeTypeDescription(challengeType)}`}
      maxWidth="600px"
    >
      <div style={{ padding: '20px' }}>
        {/* Challenge Header */}
        <div style={{ 
          background: 'rgba(255, 68, 68, 0.1)', 
          border: '1px solid rgba(255, 68, 68, 0.3)', 
          borderRadius: '8px', 
          padding: '16px', 
          marginBottom: '20px' 
        }}>
          <h3 style={{ color: '#ff4444', margin: '0 0 12px 0', textAlign: 'center' }}>
            {challengerName} {challengerLastName} vs {defenderName} {defenderLastName}
          </h3>
          <div style={{ display: 'flex', justifyContent: 'space-around', color: '#e0e0e0' }}>
            <div>
              <strong>Challenger:</strong><br />
              Position {challengerPos}<br />
              {challengerLadder}
            </div>
            <div style={{ fontSize: '24px', color: '#ff4444' }}>⚔️</div>
            <div>
              <strong>Defender:</strong><br />
              Position {defenderPos}<br />
              {defenderLadder}
            </div>
          </div>
        </div>

        {/* Challenge Details */}
        <div style={{ marginBottom: '20px' }}>
          <h4 style={{ color: '#ffc107', marginBottom: '12px' }}>Match Details</h4>
          <div style={{ 
            background: 'rgba(0, 0, 0, 0.3)', 
            borderRadius: '8px', 
            padding: '16px',
            color: '#e0e0e0'
          }}>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px', marginBottom: '12px' }}>
              <div>
                <strong>Entry Fee:</strong> ${md.entryFee}
              </div>
              <div>
                <strong>Race Length:</strong> {md.raceLength}
              </div>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px', marginBottom: '12px' }}>
              <div>
                <strong>Game Type:</strong> {md.gameType}
              </div>
              <div>
                <strong>Table Size:</strong> {md.tableSize}
              </div>
            </div>
            <div>
              <strong>Location:</strong> {md.location}
            </div>
          </div>
          
          {/* Match Fee Information */}
          <div style={{
            background: 'rgba(16, 185, 129, 0.1)',
            border: '1px solid rgba(16, 185, 129, 0.3)',
            borderRadius: '8px',
            padding: '12px',
            marginTop: '12px',
            textAlign: 'center'
          }}>
            <div style={{ color: '#10b981', fontWeight: 'bold', marginBottom: '4px' }}>
              💰 Match Fee Information
            </div>
            <div style={{ color: '#e0e0e0', fontSize: '0.9rem' }}>
              {CHALLENGE_CONFIRM_MATCH_FEE_BLURB}
            </div>
          </div>
        </div>

        {/* Position Changes */}
        <div style={{ marginBottom: '20px' }}>
          <h4 style={{ color: '#ffc107', marginBottom: '12px' }}>Position Changes</h4>
          <div style={{ 
            background: 'rgba(255, 193, 7, 0.1)', 
            border: '1px solid rgba(255, 193, 7, 0.3)', 
            borderRadius: '8px', 
            padding: '12px',
            color: '#e0e0e0',
            fontSize: '0.9rem',
            lineHeight: '1.4'
          }}>
            {getPositionChangeDescription(challengeType)}
          </div>
        </div>

        {/* Decline Status - only for received challenges (defender) */}
        {!isSentChallenge && declineStatus && (
          <div style={{ marginBottom: '20px' }}>
            <h4 style={{ color: '#ffc107', marginBottom: '12px' }}>Decline Status</h4>
            <div style={{ 
              background: declineStatus.availableDeclines > 0 ? 'rgba(16, 185, 129, 0.1)' : 'rgba(220, 38, 38, 0.1)', 
              border: declineStatus.availableDeclines > 0 ? '1px solid rgba(16, 185, 129, 0.3)' : '1px solid rgba(220, 38, 38, 0.3)', 
              borderRadius: '8px', 
              padding: '12px',
              color: '#e0e0e0',
              fontSize: '0.9rem',
              lineHeight: '1.4'
            }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
                <span>
                  <strong>Available Declines:</strong> {declineStatus.availableDeclines}/2
                </span>
                <span style={{ 
                  color: declineStatus.availableDeclines > 0 ? '#10b981' : '#dc2626',
                  fontWeight: 'bold'
                }}>
                  {declineStatus.availableDeclines > 0 ? '✅ Can Decline' : '❌ No Declines Left'}
                </span>
              </div>
              
              {declineStatus.availableDeclines === 0 && (
                <div style={{ 
                  background: 'rgba(220, 38, 38, 0.2)',
                  border: '1px solid rgba(220, 38, 38, 0.4)',
                  borderRadius: '4px',
                  padding: '8px',
                  marginTop: '8px',
                  color: '#fca5a5',
                  fontSize: '0.85rem'
                }}>
                  ⚠️ <strong>Warning:</strong> You have no declines remaining. If you decline this challenge, 
                  the challenger will move up one position and you will move down one position.
                  {declineStatus.nextResetDate && (
                    <div style={{ marginTop: '4px' }}>
                      Next decline resets in {declineStatus.daysUntilNextReset} days.
                    </div>
                  )}
                </div>
              )}
              
              {declineStatus.availableDeclines > 0 && (
                <div style={{ 
                  background: 'rgba(16, 185, 129, 0.2)',
                  border: '1px solid rgba(16, 185, 129, 0.4)',
                  borderRadius: '4px',
                  padding: '8px',
                  marginTop: '8px',
                  color: '#6ee7b7',
                  fontSize: '0.85rem'
                }}>
                  ℹ️ <strong>Decline Effect:</strong> If you decline this challenge, 
                  the challenger will move up one position and you will move down one position.
                </div>
              )}
            </div>
          </div>
        )}

        {/* Challenge Message */}
        {postContent && (
          <div style={{ marginBottom: '20px' }}>
            <h4 style={{ color: '#ffc107', marginBottom: '12px' }}>Challenge Message</h4>
            <div style={{ 
              background: 'rgba(0, 0, 0, 0.3)', 
              borderRadius: '8px', 
              padding: '12px',
              color: '#e0e0e0',
              fontSize: '0.9rem',
              lineHeight: '1.4',
              whiteSpace: 'pre-line'
            }}>
              {postContent}
            </div>
          </div>
        )}

        {/* Preferred Dates Selection - only for received challenges */}
        {!isSentChallenge && md.preferredDates && md.preferredDates.length > 0 && (
          <div style={{ marginBottom: '20px' }}>
            <h4 style={{ color: '#ffc107', marginBottom: '12px' }}>Select Match Date</h4>
            <div style={{ 
              background: 'rgba(0, 0, 0, 0.3)', 
              borderRadius: '8px', 
              padding: '12px',
              color: '#e0e0e0'
            }}>
              <p style={{ marginBottom: '12px', fontSize: '0.9rem', color: '#ccc' }}>
                Choose from the challenger's preferred dates:
              </p>
              {md.preferredDates.map((date, index) => (
                <label key={index} style={{ 
                  display: 'block', 
                  marginBottom: '8px',
                  cursor: 'pointer',
                  padding: '8px',
                  borderRadius: '4px',
                  background: selectedDate === date ? 'rgba(16, 185, 129, 0.2)' : 'transparent',
                  border: selectedDate === date ? '1px solid #10b981' : '1px solid transparent',
                  transition: 'all 0.2s ease'
                }}>
                  <input
                    type="radio"
                    name="selectedDate"
                    value={date}
                    checked={selectedDate === date}
                    onChange={(e) => setSelectedDate(e.target.value)}
                    style={{ marginRight: '8px' }}
                  />
                  {formatDateForDisplay(date, { 
                    weekday: 'long', 
                    year: 'numeric', 
                    month: 'long', 
                    day: 'numeric' 
                  })}
                </label>
              ))}
              {selectedDate && (
                <div style={{ 
                  marginTop: '12px',
                  padding: '8px',
                  background: 'rgba(16, 185, 129, 0.1)',
                  border: '1px solid rgba(16, 185, 129, 0.3)',
                  borderRadius: '4px',
                  color: '#10b981',
                  fontSize: '0.9rem'
                }}>
                  ✅ Match scheduled for: {formatDateForDisplay(selectedDate, { 
                    weekday: 'long', 
                    year: 'numeric', 
                    month: 'long', 
                    day: 'numeric' 
                  })}
                </div>
              )}
            </div>
          </div>
        )}

        {/* Response Note - only for received challenges */}
        {!isSentChallenge && (
        <div style={{ marginBottom: '20px' }}>
          <label style={{ color: '#e0e0e0', display: 'block', marginBottom: '4px' }}>
            Your Response Note (Optional)
          </label>
          <textarea
            value={userNote}
            onChange={(e) => setUserNote(e.target.value)}
            rows="3"
            placeholder="Add a note to your response..."
            style={{
              width: '100%',
              padding: '8px',
              borderRadius: '4px',
              border: '1px solid #444',
              background: '#333',
              color: '#fff',
              resize: 'vertical'
            }}
          />
        </div>
        )}

        {/* Error Display */}
        {error && (
          <div style={{ 
            background: 'rgba(255, 0, 0, 0.1)', 
            border: '1px solid #ff0000', 
            borderRadius: '4px', 
            padding: '8px', 
            marginBottom: '16px',
            color: '#ff6666'
          }}>
            {error}
          </div>
        )}

        {/* Action Buttons - hide for sent challenges (view-only) */}
        <div style={{ display: 'flex', gap: '12px', justifyContent: isSentChallenge ? 'center' : 'space-between' }}>
          {isSentChallenge ? (
            <button
              onClick={onClose}
              style={{
                padding: '12px 24px',
                background: '#10b981',
                color: 'white',
                border: 'none',
                borderRadius: '8px',
                cursor: 'pointer',
                fontSize: '1rem',
                fontWeight: 'bold'
              }}
            >
              Close
            </button>
          ) : (
            <>
              <button
                onClick={handleDecline}
                disabled={loading || loadingDeclineStatus || (declineStatus && declineStatus.availableDeclines === 0)}
                style={{
                  padding: '12px 24px',
                  background: loading || loadingDeclineStatus || (declineStatus && declineStatus.availableDeclines === 0) ? '#666' : '#dc2626',
                  color: 'white',
                  border: 'none',
                  borderRadius: '8px',
                  cursor: loading || loadingDeclineStatus || (declineStatus && declineStatus.availableDeclines === 0) ? 'not-allowed' : 'pointer',
                  fontSize: '1rem',
                  fontWeight: 'bold'
                }}
              >
                {loading ? 'Processing...' : 
                 loadingDeclineStatus ? 'Loading...' :
                 (declineStatus && declineStatus.availableDeclines === 0) ? 'No Declines Left' : 'Decline'}
              </button>
              
              <div style={{ display: 'flex', gap: '8px' }}>
                <button
                  onClick={handleCounter}
                  disabled={loading}
                  style={{
                    padding: '12px 24px',
                    background: loading ? '#666' : '#f59e0b',
                    color: 'white',
                    border: 'none',
                    borderRadius: '8px',
                    cursor: loading ? 'not-allowed' : 'pointer',
                    fontSize: '1rem',
                    fontWeight: 'bold'
                  }}
                >
                  Counter
                </button>
                
                <button
              onClick={handleAccept}
              disabled={loading || (md.preferredDates && md.preferredDates.length > 0 && !selectedDate)}
              style={{
                padding: '12px 24px',
                background: loading || (md.preferredDates && md.preferredDates.length > 0 && !selectedDate) ? '#666' : 'linear-gradient(135deg, #10b981, #059669)',
                color: 'white',
                border: 'none',
                borderRadius: '8px',
                cursor: loading || (md.preferredDates && md.preferredDates.length > 0 && !selectedDate) ? 'not-allowed' : 'pointer',
                fontSize: '1rem',
                fontWeight: 'bold'
              }}
            >
              {loading ? 'Processing...' : 
               (md.preferredDates && md.preferredDates.length > 0 && !selectedDate) ? 'Select Date First' : 'Accept'}
                </button>
              </div>
            </>
          )}
        </div>

        {/* Deadline Warning */}
        <div style={{ 
          marginTop: '16px',
          padding: '12px',
          background: 'rgba(255, 193, 7, 0.1)',
          border: '1px solid rgba(255, 193, 7, 0.3)',
          borderRadius: '4px',
          color: '#ffc107',
          fontSize: '0.9rem',
          textAlign: 'center'
        }}>
          ⏰ This challenge expires on {deadline ? formatDateForDisplay(deadline) : 'N/A'}
        </div>
      </div>
      
      {/* Counter-Proposal Modal */}
      <LadderCounterProposalModal
        isOpen={showCounterModal}
        onClose={() => setShowCounterModal(false)}
        challenge={challenge}
        currentUser={currentUser}
        onCounterProposalSubmitted={onChallengeResponse}
      />
    </DraggableModal>
  );
};

export default LadderChallengeConfirmModal;
